<?php
require __DIR__.'/../app/bootstrap.php';$u=require_admin();$id=(int)param('id');$a=one('SELECT s.*,u.full_name,u.email,u.phone FROM seller_applications s JOIN users u ON u.id=s.user_id WHERE s.id=?',[$id]);if(!$a)fail(404,t('Seller application not found.'));$title=t('Review ').$a['business_name'];$err=[];
if(post()){
 $decision=val('decision');$note=val('review_note');
 if(!in_array($decision,['approved','rejected']))$err[]=t('Choose approve or reject.');
 if($decision==='rejected' && !text_valid($note,10,1500))$err[]=t('Provide a rejection reason between 10 and 1500 characters.');
 if(mb_strlen($note)>1500)$err[]=t('The review note must be under 1500 characters.');
 if(!$err){db()->beginTransaction();$changed=q("UPDATE seller_applications SET status=?,review_note=?,reviewed_by=?,reviewed_at=? WHERE id=? AND status='pending'",[$decision,$note,$u['id'],now(),$id])->rowCount();
  if(!$changed){db()->rollBack();$err[]=t('This application has already been reviewed. Reload to see the current status.');}
  else{q('UPDATE users SET role=? WHERE id=?',[$decision==='approved'?'seller':'customer',$a['user_id']]);audit((int)$u['id'],t('Seller application ').$decision,$id);
   queue_mail($a['email'],$decision==='approved'?t('Your seller profile is approved'):'Update on your seller application',"Hello {$a['full_name']},\nYour application for {$a['business_name']} has been {$decision}.\n".($note?"Review note: {$note}\n":'').url('seller/status.php'));db()->commit();mail_after_commit();flash(t('Application ').$decision.'. A notification email has been queued.');go('admin/application.php?id='.$id);}
 }
}
require ROOT.'/app/workspace-start.php'; ?>
<div class="dash-header"><div><span class="heading-kicker"><?=e(t('SELLER APPLICATION'))?></span><h1><?=e($a['business_name'])?></h1><p class="dash-sub"><?=e(t('Submitted'))?> <?=e(local_time($a['submitted_at']))?></p></div><a class="pill" href="<?=e(url('admin/applications.php'))?>"><?=e(t('← Applications'))?></a></div><?php errors($err); ?><div class="two-columns"><section class="panel"><img class="business-logo" src="<?=e(image_url($a['logo_id']))?>" alt="<?=e(t('Business logo'))?>"><h2><?=e(t('Business details'))?></h2><dl class="details"><dt><?=e(t('Owner'))?></dt><dd><?=e($a['full_name'])?></dd><dt><?=e(t('Email'))?></dt><dd><?=e($a['email'])?></dd><dt><?=e(t('Business phone'))?></dt><dd><?=e($a['business_phone'])?></dd><dt><?=e(t('Address'))?></dt><dd><?=nl2br(e($a['address']))?></dd><dt><?=e(t('Status'))?></dt><dd><span class="chip <?=$a['status']==='pending'?'pending':''?>"><?=e(t(ucfirst($a['status'])))?></span></dd></dl></section><section class="panel"><h2><?=e(t('Private identity documents'))?></h2><p class="hint"><?=e(t('For application review only. Do not share or download to public storage.'))?></p><p><?=e(t('CNIC:'))?> <strong><?=e(decrypt_cnic($a['cnic_encrypted']))?></strong></p><div class="identity-images"><a href="<?=e(image_url($a['cnic_front']))?>" target="_blank" rel="noopener"><img src="<?=e(image_url($a['cnic_front']))?>" alt="<?=e(t('CNIC front'))?>"></a><a href="<?=e(image_url($a['cnic_back']))?>" target="_blank" rel="noopener"><img src="<?=e(image_url($a['cnic_back']))?>" alt="<?=e(t('CNIC back'))?>"></a></div></section></div><section class="panel list-panel"><?php if($a['status']==='pending'): ?><h2><?=e(t('Your decision'))?></h2><form method="post" data-confirm="Save this seller application decision?"><?=csrf()?><?php area('review_note',t('Review note (required for rejection)'),val('review_note'),'maxlength="1500"'); ?><div class="row-actions space-top"><button class="pill primary" name="decision" value="approved"><?=e(t('Approve seller'))?></button><button class="pill danger" name="decision" value="rejected"><?=e(t('Reject application'))?></button></div></form><?php else: ?><h2><?=e(t('Review completed'))?></h2><p><?=e(local_time($a['reviewed_at']))?></p><p><?=e($a['review_note']?:t('No additional review note.'))?></p><?php endif ?></section><?php require ROOT.'/app/workspace-end.php'; ?>
